package com.huy.enterprise.dashboard; import com.huy.enterprise.alert.AlertRepository; import com.huy.enterprise.common.enums.*; import com.huy.enterprise.inventory.InventoryItemRepository; import com.huy.enterprise.order.PurchaseOrderRepository; import com.huy.enterprise.risk.RiskEventRepository; import com.huy.enterprise.supplier.SupplierRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.List; @Service @RequiredArgsConstructor public class DashboardService {private final SupplierRepository suppliers;private final PurchaseOrderRepository orders;private final RiskEventRepository risks;private final AlertRepository alerts;private final InventoryItemRepository inventory;public DashboardSummaryResponse getSummary(){return new DashboardSummaryResponse(suppliers.count(),suppliers.countByRiskLevel(RiskLevel.HIGH),orders.count(),orders.countByStatus(PurchaseOrderStatus.DELAYED),risks.countByStatus(RiskEventStatus.OPEN),alerts.countByStatusIn(List.of(AlertStatus.NEW,AlertStatus.READ)),inventory.countLowStockItems());}}
